<template>
  <PageShell class="life-page monthly-review-page" variant="standard">

    <PageHeader :title="`我的 ${month.slice(0,4)} 年 ${Number(month.slice(5))} 月`" description="把真实记录与自己的想法留在一起，不必每个月都写。"><template #breadcrumbs><nav class="life-breadcrumb" aria-label="当前位置"><RouterLink :to="lifeReturn">生活</RouterLink><span>/</span><span aria-current="page">月度回顾</span></nav></template><template #actions><RouterLink :to="lifeReturn">返回生活</RouterLink></template></PageHeader>
    <div class="review-toolbar"><label for="review-month">回顾月份</label><el-date-picker :key="pickerKey" id="review-month" :model-value="month" type="month" value-format="YYYY-MM" format="YYYY 年 MM 月" aria-label="回顾月份" :clearable="false" :disabled="busy" @update:model-value="selectMonth" /><el-button :disabled="busy || loading || Boolean(historyID)" @click="regenerate">重新汇总</el-button><el-select v-if="savedMonths.length" :model-value="month" placeholder="已保存回顾" aria-label="已保存回顾" :disabled="busy" @update:model-value="selectMonth"><el-option v-for="row in savedMonths" :key="row.month" :label="row.month + ' · 已保存'" :value="row.month" /></el-select></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false"><el-button :disabled="busy" text @click="retry">重试读取</el-button></el-alert>
    <div v-loading="loading" class="review-content">
      <template v-if="document">
        <div class="review-status"><span>{{ document.facts.from }} — {{ document.facts.to }} · {{ document.facts.timezone }}</span><span v-if="month > reviewCurrentMonth()">月份尚未开始</span><span v-else-if="month===reviewCurrentMonth()">进行中的月份，记录可能继续增加</span><strong>{{ historyID ? '以前保存的事实版本' : candidate ? '重新汇总预览 · 尚未确认保存' : saved ? '已保存的月度档案' : '月度预览 · 尚未保存' }}</strong></div>
        <p class="life-muted">汇总于 {{ localTime(document.facts.generated_at) }}<template v-if="saved"> · 首次保存 {{ localTime(saved.created_at) }} · 最近修改 {{ localTime(saved.updated_at) }}</template>。{{ saved && !candidate ? '事实摘要保留保存时的内容，原始来源可能已经变化。' : '这是当前记录的汇总，保存后形成独立月度档案。' }}</p>
        <el-alert v-if="candidate" title="这是新汇总的预览，原回顾仍保留。个人心得保持原输入，确认保存后才采用新事实。" type="info" :closable="false"><el-button text @click="discardPreview">返回已保存版本</el-button></el-alert>
        <div class="review-sections">
          <section><h2>项目与行动</h2><p class="life-muted">{{ document.facts.actions.filter(i=>i.kind==='task').length }} 条有可靠完成时间的任务 · {{ document.facts.actions.filter(i=>i.kind==='project').length }} 个项目成果</p><ReviewRecordList :items="document.facts.actions" empty="本月没有可确认完成日期的行动记录。" /></section>
          <section><h2>学习与探索</h2><p class="life-muted">完成记录与明确发生的学习活动；不由回答次数推断掌握。</p><ReviewRecordList :items="document.facts.learning" empty="本月没有可确认时间的学习或探索记录。" /></section>
          <section><h2>生活经历</h2><p class="life-muted">按经历发生日期收录，补录日期不改变归属月份。</p><ReviewRecordList :items="document.facts.events" empty="本月还没有记录生活经历。" /></section>
          <section><h2>财务与资产</h2><p v-if="!document.facts.finance.length" class="life-muted">本月暂无账本数据。</p><article v-for="(row,index) in document.facts.finance" :key="row.ledger_id + ':' + index" class="review-finance"><h3>{{ row.name }}<span v-if="row.currency"> · {{ row.currency }}</span></h3><template v-if="row.summary"><dl class="review-money"><div><dt>收入</dt><dd>{{ financeMoney(row.summary.income_minor) }}</dd></div><div><dt>支出</dt><dd>{{ financeMoney(row.summary.expense_minor) }}</dd></div><div><dt>收支差额</dt><dd>{{ financeMoney(row.summary.difference_minor) }}</dd></div></dl><p class="life-muted">来源：钱迹 · 账本实际覆盖 {{ row.summary.coverage_from }} — {{ row.summary.coverage_to }}<span v-if="row.summary.last_import"> · 导入 {{ localTime(row.summary.last_import) }}</span></p><p class="life-muted">{{ document.facts.in_progress ? '汇总时期间尚未结束；' : '' }}覆盖日期及自然月结束均不能证明账本完整。收支差额不代表净资产变化。</p><ul class="review-categories"><li v-for="category in row.summary.categories.slice(0,3)" :key="category.name"><span>{{ category.name || '未分类' }}</span><b>{{ financeMoney(category.amount_minor) }} {{ row.currency }}</b></li></ul></template><p v-else class="life-muted">本月暂无该账本、币种的账目，不能据此确认收支为零。</p><RouterLink v-if="row.available" :to="{ path:'/life/finance',query:{tab:'overview',ledger:row.ledger_id,year:month.slice(0,4),month:month.slice(5),currency:row.currency,life_view:'timeline'} }">查看财务来源</RouterLink><span v-else class="life-muted">原始账本已不可用。</span></article>
            <h3>本月资产记录</h3><p v-if="!document.facts.assets.length" class="life-muted">没有记录资产快照，不推算月末资产。</p><article v-for="row in document.facts.assets" :key="row.snapshot.id" class="review-record"><div class="life-metadata"><time>{{ row.snapshot.snapshot_date }}</time><span>{{ row.snapshot.complete ? '完整范围' : '不完整范围' }}</span></div><p class="review-record-detail">{{ row.snapshot.complete ? '资产总额' : '已填资产合计' }} {{ money(row.snapshot.asset_total_minor) }} · 负债 {{ money(row.snapshot.debt_minor) }} · {{ row.snapshot.complete ? '净资产' : '已填范围差额' }} {{ money(row.snapshot.net_asset_minor) }} · CNY</p><p v-if="row.snapshot.note" class="review-record-detail">{{ row.snapshot.note }}</p><RouterLink v-if="row.available" :to="{path:'/life/finance',query:{tab:'assets',asset:row.snapshot.id}}">查看快照</RouterLink><span v-else class="life-muted">原始快照已不可用。</span></article>
          </section>
        </div>
        <section v-if="document.facts.goals.length" class="review-goals"><h2>长期目标的变化</h2><ReviewRecordList :items="document.facts.goals" empty="本月没有阶段变化。" /></section>
        <section class="review-personal"><h2>我的月度回顾</h2><p class="life-muted">都可以留空。感受属于你，不由系统评分或生成。</p><template v-if="historyID"><p v-if="document.archived_personal?.memorable" class="review-record-detail">值得记住：{{ document.archived_personal.memorable }}</p><p v-if="document.archived_personal?.thoughts" class="review-record-detail">感受与思考：{{ document.archived_personal.thoughts }}</p><p v-if="document.archived_personal?.next_focus" class="review-record-detail">下月关注：{{ document.archived_personal.next_focus }}</p><ExternalLink v-if="document.archived_personal?.external_url" :url="document.archived_personal.external_url" name="当时的外部笔记" /><el-button @click="returnCurrent">返回当前回顾</el-button></template>
          <el-form v-else label-position="top" @submit.prevent="save"><el-form-item label="这个月最值得记住的事情"><el-input v-model="personal.memorable" type="textarea" :rows="3" maxlength="10000" :disabled="busy" /></el-form-item><el-form-item label="这个月的感受或思考"><el-input v-model="personal.thoughts" type="textarea" :rows="4" maxlength="10000" :disabled="busy" /></el-form-item><el-form-item label="下个月想关注什么"><el-input v-model="personal.next_focus" type="textarea" :rows="3" maxlength="10000" :disabled="busy" /></el-form-item><el-form-item label="Obsidian 或外部月度笔记（可选）"><el-input v-model="personal.external_url" placeholder="obsidian://open?... 或 https://" :disabled="busy" maxlength="2048" /></el-form-item><ExternalLink v-if="safeExternalLink(personal.external_url) && personal.external_url" :url="personal.external_url" name="我的月度笔记" /><div class="review-save"><el-button type="primary" :loading="busy" @click="save">{{ candidate ? '确认更新事实并保存回顾' : saved ? '保存个人回顾' : '保存本月回顾' }}</el-button><span class="life-muted">{{ saved ? '编辑心得不会自动重新汇总事实。' : '保存当前事实摘要与个人回顾。' }}</span></div></el-form>
        </section>
        <details v-if="saved && (current?.history?.length ?? 0)>1" class="review-history"><summary>以前保存的事实版本</summary><el-button v-for="version in current?.history" :key="version.id" text :disabled="busy || loading || version.id===document.facts_id" @click="openHistory(version.id)">汇总 {{ localTime(version.generated_at) }} · 确认 {{ localTime(version.confirmed_at) }}</el-button></details>
        <details class="review-limits"><summary>数据范围与历史限制</summary><p v-for="limit in document.facts.limits" :key="limit" class="life-muted">{{ limit }}</p></details>
      </template>
    </div>
  </PageShell>
</template>
<script setup lang="ts">
import PageShell from '@/components/PageShell.vue'
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { onBeforeRouteLeave, onBeforeRouteUpdate, useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import PageHeader from '@/components/PageHeader.vue'
import ExternalLink from '@/components/ExternalLink.vue'
import ReviewRecordList from '@/components/life/ReviewRecordList.vue'
import { getReview, listReviews, previewReview, reviewHistory, saveReview, reviewCurrentMonth, type MonthlyReview, type PersonalReview, type ReviewDocument } from '@/api/reviews'
import { financeMoney } from '@/api/finance'
import { safeExternalLink } from '@/utils/externalLinks'
import '@/life.css'
import '@/reviews.css'
const route=useRoute(),router=useRouter()
const validMonth=(value:unknown)=>typeof value==='string' && /^(19\d{2}|[2-9]\d{3})-(0[1-9]|1[0-2])$/.test(value) && !value.startsWith('9999')
const pickerKey=ref(0)
const month=ref(validMonth(route.query.month)?String(route.query.month):reviewCurrentMonth()),current=ref<ReviewDocument>(),candidate=ref<ReviewDocument>(),historical=ref<ReviewDocument>(),historyID=ref<number>(),loading=ref(false),busy=ref(false),error=ref(''),savedMonths=ref<MonthlyReview[]>([])
const personal=reactive<PersonalReview>({memorable:'',thoughts:'',next_focus:'',external_url:''})
let sequence=0,disposed=false
const initial=ref(JSON.stringify(personal))
const document=computed(()=>historical.value ?? candidate.value ?? current.value),saved=computed(()=>current.value?.review),dirty=computed(()=>JSON.stringify(personal)!==initial.value)
const lifeReturn=computed(()=>({path:'/life',query:{view:route.query.life_view==='goals'?'goals':undefined,domain:typeof route.query.life_domain==='string'?route.query.life_domain:undefined}}))
const money=(value:string|null)=>value===null?'未记录':financeMoney(value)
const localTime=(value:string)=>new Date(value).toLocaleString('zh-CN')
const message=(e:unknown)=>e instanceof Error?e.message:'回顾暂时无法读取，请重试。'
async function allowLeave(){if(busy.value)return false;if(dirty.value || candidate.value){try{await ElMessageBox.confirm('离开会放弃尚未保存的心得或重新汇总预览。','未保存的回顾',{confirmButtonText:'放弃修改',cancelButtonText:'继续填写'})}catch{return false}};return true}
async function load(reset=true){const token=++sequence,selected=month.value;loading.value=true;error.value='';try{let doc=await getReview(selected);if(!doc.review)doc=await previewReview(selected);if(disposed || token!==sequence)return;current.value=doc;candidate.value=undefined;historical.value=undefined;historyID.value=undefined;if(reset){Object.assign(personal,{memorable:doc.review?.memorable ?? '',thoughts:doc.review?.thoughts ?? '',next_focus:doc.review?.next_focus ?? '',external_url:doc.review?.external_url ?? ''});initial.value=JSON.stringify(personal)};savedMonths.value=await listReviews()}catch(e){if(token===sequence)error.value=message(e)}finally{if(token===sequence)loading.value=false}}
async function selectMonth(value:string){if(!validMonth(value)||value===month.value)return;if(!(await allowLeave())){pickerKey.value++;return};month.value=value;current.value=undefined;candidate.value=undefined;historical.value=undefined;Object.assign(personal,{memorable:'',thoughts:'',next_focus:'',external_url:''});initial.value=JSON.stringify(personal);await router.replace({query:{...route.query,month:value}});await load()}
async function regenerate(){if(busy.value || loading.value || historyID.value)return;const token=++sequence;loading.value=true;error.value='';try{const doc=await previewReview(month.value);if(disposed || token!==sequence)return;if(saved.value)candidate.value=doc;else current.value=doc}catch(e){if(token===sequence)error.value=message(e)}finally{if(token===sequence)loading.value=false}}
function discardPreview(){candidate.value=undefined;error.value=''}
async function retry(){await load(!dirty.value)}
async function save(){if(busy.value || loading.value || !document.value || historyID.value)return;if(personal.external_url.trim()&&!safeExternalLink(personal.external_url.trim())){error.value='链接仅支持 http、https 和有效的 Obsidian open URI。';return};if(candidate.value){try{await ElMessageBox.confirm('采用预览中的新事实？现有事实版本及原心得会保留，当前填写的心得一起保存。','确认更新月度档案',{confirmButtonText:'确认更新',cancelButtonText:'继续预览'})}catch{return}};busy.value=true;error.value='';try{const result=await saveReview(month.value,{...personal,facts_id:document.value.facts_id,version:saved.value?.version ?? 0,confirm_replace:Boolean(candidate.value)});if(disposed)return;current.value=result;candidate.value=undefined;initial.value=JSON.stringify(personal);savedMonths.value=[result.review!,...savedMonths.value.filter(r=>r.month!==month.value)].sort((a,b)=>b.month.localeCompare(a.month));ElMessage.success('月度回顾已保存')}catch(e){error.value=message(e)}finally{busy.value=false}}
async function openHistory(id:number){if(id===current.value?.facts_id){returnCurrent();return};if(!(await allowLeave()))return;const token=++sequence;loading.value=true;try{const doc=await reviewHistory(month.value,id);if(token===sequence && !disposed){historical.value=doc;historyID.value=id;candidate.value=undefined;Object.assign(personal,{memorable:saved.value?.memorable ?? '',thoughts:saved.value?.thoughts ?? '',next_focus:saved.value?.next_focus ?? '',external_url:saved.value?.external_url ?? ''});initial.value=JSON.stringify(personal)}}catch(e){error.value=message(e)}finally{if(token===sequence)loading.value=false}}
function returnCurrent(){historical.value=undefined;historyID.value=undefined}
onBeforeRouteLeave(allowLeave)
onBeforeRouteUpdate(async to=>{const next=validMonth(to.query.month)?String(to.query.month):reviewCurrentMonth();if(next===month.value)return true;if(!(await allowLeave()))return false;month.value=next;current.value=undefined;candidate.value=undefined;Object.assign(personal,{memorable:'',thoughts:'',next_focus:'',external_url:''});initial.value=JSON.stringify(personal);void load();return true})
onMounted(()=>load())
onBeforeUnmount(()=>{disposed=true;++sequence})
</script>
